/// <summary>The game's camera kinds (CAMERA_MODE_*) this port carries. The runtime record of each is in <see cref="SmsCamKinds"/>.</summary>
public enum SmsCamKind
{
    Follow,        // CAMERA_MODE 0x00, /Camera/kindfollow.prm: the default on an ordinary stage area
    Delfino,       // CAMERA_MODE 0x14, /Camera/kinddelfino.prm: Delfino Plaza (map 7) areas
    Indoor,        // CAMERA_MODE 0x0E, /Camera/kindindoor.prm: isMarioIndoor (an indoors ground type)
    Swimming,      // CAMERA_MODE 0x2A, /Camera/kindswimming.prm: the SWIM_* statuses off map 7
    AquaticTurbo,  // CAMERA_MODE 0x3C, /Camera/kindaquaticturbo.prm: the turbo dash in water off map 7
    Turbo,         // CAMERA_MODE 0x27, /Camera/kindturbo.prm: MARIO_FLAG_FLUDD_EMITTING: the turbo dash
    Hang,          // CAMERA_MODE 0x0F, /Camera/kindhang.prm: the ROOF family (status bit 0x200000), not KICK_ROOF_ROLL_UP
    Fence,         // CAMERA_MODE 0x35, /Camera/kindfence.prm: the FENCE_* statuses
    WallJump,      // CAMERA_MODE 0x03, /Camera/kindwalljump.prm: WALL_JUMP / WALL_SLIDE
    HipAttack,     // CAMERA_MODE 0x04, /Camera/kindhipattack.prm: HIP_DROP
    Hovering,      // CAMERA_MODE 0x12, /Camera/kindhovering.prm: ROCKET / ROCKET_LANDING with the hover nozzle (4)
    RocketJump,    // CAMERA_MODE 0x05, /Camera/kindrocketjump.prm: ROCKET / ROCKET_LANDING with any other nozzle
    LookDown,      // CAMERA_MODE 0x2D, /Camera/kindlookdown.prm: an area kind (a cube asks for it)
    LNormal,       // CAMERA_MODE 0x07, /Camera/kindlnormal.prm: the L (Y) camera: MarioYCam.cs owns it; here for the blend lengths
    Wire,          // CAMERA_MODE 0x06, /Camera/kindwire.prm: on top of a wire (TMapWire): WIRE_WAIT / WALK / ROLL
    WireHang,      // CAMERA_MODE 0x10, /Camera/kindwirehang.prm: hanging or rolling under a wire: WIRE_HANG family
}

